(7649063, 1243778, 112739, '<td valign="top">Great idea and execution Larry! Saw this laughed out loud. Congrats on the Blue, you earned it for sure!</td>', 'Great idea and execution Larry! Saw this laughed out loud. Congrats on the Blue, you earned it for sure!', '2019-12-27 13:00:14.000000', NULL, 0),
(7649085, 1243875, 3306, '<td valign="top">I must have voted on this challenge late at night. I did not appreciate how beautiful a picture this is. The lighting, DOF, balance, and composition are perfect. Congrats on the red, but I honestly feel you deserve the blue.</td>', 'I must have voted on this challenge late at night. I did not appreciate how beautiful a picture this is. The lighting, DOF, balance, and composition are perfect. Congrats on the red, but I honestly feel you deserve the blue.', '2019-12-28 07:57:56.000000', NULL, 0),
