(7649092, 1243956, 3306, '<td valign="top">I congratulate you on your dedication! I like the socks.</td>', 'I congratulate you on your dedication! I like the socks.', '2019-12-28 08:16:55.000000', NULL, 0),
(7649093, 1243883, 3306, '<td valign="top">Interesting technique.  The title suggests the feet are moving quickly, but the background looks like it is moving at the same speed so I am guessing they were both stationary and you moved the camera. I wonder how it would have looked if you kept the camera steady and swung the shoes from the laces?  He was quite an athlete!</td>', 'Interesting technique.  The title suggests the feet are moving quickly, but the background looks like it is moving at the same speed so I am guessing they were both stationary and you moved the camera. I wonder how it would have looked if you kept the camera steady and swung the shoes from the laces?  He was quite an athlete!', '2019-12-28 08:26:25.000000', NULL, 0),
(7649094, 1243954, 3306, '<td valign="top">Interesting capture. I find myself wondering if it is a reflection or you are looking through a porthole of some kind?</td>', 'Interesting capture. I find myself wondering if it is a reflection or you are looking through a porthole of some kind?', '2019-12-28 08:29:46.000000', NULL, 0),
(7649095, 1243894, 3306, '<td valign="top">I agree. Great potential. Hard to see the shoes though.</td>', 'I agree. Great potential. Hard to see the shoes though.', '2019-12-28 08:31:19.000000', NULL, 0),
